$('complete').onclick=async()=>{if(!$('body').value.trim())return toast('Add at least one sentence or quote before completing.');clearTimeout(timer);timer=null;await save();if(!persistOk)return;const e=current();if(!e||e.completed)return;e.completed=true;e.completedAt=Date.now();try{await writeStore('entries',entries);render();toast('Journal marked complete. You can keep editing whenever you like.')}catch{e.completed=false;toast('Could not mark this journal complete. Your writing is still available.')}};
$('prevDay').onclick=()=>{let d=asDate(selected);d.setDate(d.getDate()-1);navigate(dateKey(d))};$('nextDay').onclick=()=>{let d=asDate(selected);d.setDate(d.getDate()+1);if(dateKey(d)<=dateKey())navigate(dateKey(d))};$('goToday').onclick=$('todayNav').onclick=()=>navigate(dateKey());$('historyNav').onclick=async()=>{await window.JournalVoice?.stop();await save();showHistory(true)};$('search').oninput=renderHistory;$('prevMonth').onclick=()=>{month.setMonth(month.getMonth()-1);renderCalendar()};$('nextMonth').onclick=()=>{month.setMonth(month.getMonth()+1);renderCalendar()};
