function renderPhotos(){let e=current(),photos=e?.photos||[],can=editable();$('photoCount').textContent=photos.length+' / 3';$('photos').innerHTML=photos.map((p,i)=>`<div class="photo"><img src="${p.src}" alt="${esc(p.caption||'A moment from your day')}"><input data-caption="${i}" placeholder="A few words about this moment…" value="${esc(p.caption)}" maxlength="160" aria-label="Caption for photo ${i+1}" ${can?'':'readonly'}>${can?`<div class="photo-tools"><button data-up="${i}" aria-label="Move photo earlier" ${i===0?'disabled':''}>↑</button><button data-down="${i}" aria-label="Move photo later" ${i===photos.length-1?'disabled':''}>↓</button><button data-remove="${i}" aria-label="Remove photo">×</button></div>`:''}</div>`).join('');$('photos').querySelectorAll('[data-caption]').forEach(el=>el.oninput=()=>{e.photos[+el.dataset.caption].caption=el.value;markEntryChanged(e);clearTimeout(timer);timer=setTimeout(()=>{timer=null;save()},350)});['up','down','remove'].forEach(action=>$('photos').querySelectorAll('[data-'+action+']').forEach(b=>b.onclick=async()=>{let i=+b.dataset[action];if(action==='remove')photos.splice(i,1);else {let j=action==='up'?i-1:i+1;[photos[i],photos[j]]=[photos[j],photos[i]]}markEntryChanged(e);await save();renderPhotos();$('addPhoto').disabled=photos.length>=3}))}
$('addPhoto').onclick=()=>$('photoInput').click();$('photoInput').onchange=async e=>{if(!editable())return;let entry=createEntry(),files=[...e.target.files];for(const file of files.slice(0,3-entry.photos.length)){if(!file.type.startsWith('image/')){toast('Choose an image file.');continue}try{let url=URL.createObjectURL(file),img=new Image();await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src=url});let scale=Math.min(1,1400/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=img.width*scale;c.height=img.height*scale;c.getContext('2d').drawImage(img,0,0,c.width,c.height);entry.photos.push({src:c.toDataURL('image/jpeg',.82),caption:''});URL.revokeObjectURL(url)}catch{toast('This photo could not be opened. Try a JPEG or PNG.')}}markEntryChanged(entry);await save();renderPhotos();$('addPhoto').disabled=entry.photos.length>=3;e.target.value=''};

$('more').onclick=()=>{modal('Your journal, your way','<button class="option" id="flareOption">✧ Flare access <small>Coming later · No journal content is shared with Flare.</small></button><button class="option" id="lockOption">♧ Privacy lock <small>Coming later · The app is private to your ChatGPT account.</small></button><button class="option" id="aiOption">✎ Shape my words with AI <small>Not connected · Your original writing stays as you wrote it.</small></button><button class="option" id="deleteOption">Delete journal <small>Coming later · Deletion is not enabled.</small></button>');['flareOption','lockOption','aiOption','deleteOption'].forEach(id=>$(id).onclick=()=>toast('This feature is not connected in this version.'))};
function applySettings(){document.body.dataset.theme=settings.theme;$('profileName').textContent=settings.name||'Your space';document.querySelector('.avatar').textContent=(settings.name||'R')[0].toUpperCase()}
$('settings').onclick=()=>{modal('Make yourself at home',`<label for="displayName">Your name (optional)</label><input type="text" id="displayName" value="${esc(settings.name)}" maxlength="60" placeholder="What should we call you?"><label>Page atmosphere <select id="theme"><option value="sage">Golden Haze · Sage</option><option value="sky">Quiet Sky</option><option value="rose">Electric Rose</option><option value="night">Midnight Bloom</option></select></label><p>Your journal saves automatically. The save status shows when changes reach Supabase or are waiting on this device. Completion is only a visual marker on this browser. Export a backup to keep another copy.</p><button class="primary" id="saveSettings">Save preferences</button> <button class="secondary" id="backup">Export backup</button> <button class="secondary" id="restore">Restore backup</button><input type="file" id="restoreFile" accept="application/json" hidden>`);$('theme').value=settings.theme;$('saveSettings').onclick=async()=>{settings.name=$('displayName').value.trim();settings.theme=$('theme').value;try{await writeStore('settings',settings);applySettings();$('modal').close();toast('Your space, a little more you.')}catch{toast('Could not save preferences.')}};$('backup').onclick=()=>download(new Blob([JSON.stringify({format:'echo27-journal-v1',entries,settings})],{type:'application/json'}),'echo27-journal-backup.json');$('restore').onclick=()=>$('restoreFile').click();$('restoreFile').onchange=async e=>{try{let data=JSON.parse(await e.target.files[0].text());if(data.format!=='echo27-journal-v1'||!data.entries||typeof data.entries!=='object')throw Error();let clean={};for(const [key,v]of Object.entries(data.entries)){if(!/^\d{4}-\d{2}-\d{2}$/.test(key)||v.date!==key||typeof v.text!=='string'||!Array.isArray(v.photos)||v.photos.length>3||v.photos.some(p=>!/^data:image\/(jpeg|png|webp);base64,/.test(p.src)))throw Error();clean[key]={date:key,title:String(v.title||'').slice(0,160),text:v.text,language:String(v.language||'en-IN').slice(0,35),mood:String(v.mood||''),photos:v.photos.map(p=>({src:p.src,caption:String(p.caption||'')})),completed:!!v.completed,completedAt:Number(v.completedAt)||0,createdAt:Number(v.createdAt)||Date.now(),updatedAt:Number(v.updatedAt)||0,unlockedUntil:Number(v.unlockedUntil)||0}}let merged={...entries};for(let [k,v]of Object.entries(clean))if(!merged[k]||v.updatedAt>merged[k].updatedAt)merged[k]=v;await writeStore('entries',merged);entries=merged;localRevision++;window.JournalCloud?.changed();$('modal').close();render();toast('Backup restored. Newer entries were kept.')}catch{toast('Could not restore this file. Choose a valid ECHO27 backup.')}}};
$('help').onclick=()=>modal('A little space to be yourself',`<p>Write a sentence, tell a story, or keep a small moment. No coaching, no judgment.</p><p><b>Your daily page:</b> writing saves automatically while you type. Complete journal adds a visual marker on this browser; you can keep editing completed pages and earlier days.</p><p><b>Saving:</b> the save status shows when your journal reaches Supabase. When offline, changes remain on this device and retry after reconnecting. Export a backup to keep another copy.</p><p><b>Voice typing:</b> select English, Tamil, Telugu, Malayalam, or Hindi, then click Speak your thoughts. Soniox transcribes your microphone audio; confirmed words save automatically. Click Stop listening to finish. Voice typing needs an internet connection and a configured Soniox API key.</p><p>AI rewriting, payments, Privacy lock, Flare access, and Delete are not connected.</p><p>Dates follow your device timezone: ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}.</p>`);
