$('export').onclick=async()=>{await save();if(!current()?.text.trim())return toast('Write at least a sentence or quote before exporting.');modal('A page worth keeping','<p>Your date and ECHO27 signature always travel with your words. Every word is included; long entries become multiple story cards.</p><label><input type="checkbox" id="exportPhotos" checked> Include photos and captions</label><label><input type="checkbox" id="exportName" '+(settings.name?'checked':'disabled')+'> Include my name'+(settings.name?'':' (set it in preferences)')+'</label><button class="primary" id="imageExport">Download story cards</button> <button class="secondary" id="pdfExport">Print / Save as PDF</button><p><small>Story cards are 1080 × 1920. For PDF, choose “Save as PDF” in your browser’s print dialog.</small></p><div id="exportResults"></div>');$('imageExport').onclick=exportImages;$('pdfExport').onclick=exportPDF};
function wrap(ctx,text,max){let lines=[];for(let para of text.split('\n')){if(!para){lines.push('');continue}let line='';for(let word of para.split(/\s+/)){if(ctx.measureText(word).width>max){if(line){lines.push(line);line=''}let piece='';for(let char of word){if(ctx.measureText(piece+char).width>max){lines.push(piece);piece=''}piece+=char}line=piece}else if(ctx.measureText(line+(line?' ':'')+word).width>max){lines.push(line);line=word}else line+=(line?' ':'')+word}lines.push(line)}return lines}
async function exportImages(){let e=current(),includePhotos=$('exportPhotos').checked,includeName=$('exportName').checked,results=$('exportResults');results.innerHTML='Preparing every word…';$('imageExport').disabled=true;try{await document.fonts.ready;let measure=document.createElement('canvas').getContext('2d');measure.font='36px Georgia';let content=[...wrap(measure,e.title||'A little of my day',880),'',...wrap(measure,e.text,880)];let pages=[];for(let i=0;i<content.length;i+=27)pages.push({lines:content.slice(i,i+27)});if(includePhotos)for(let p of e.photos){let captions=wrap(measure,p.caption,880);pages.push({photo:p,lines:captions.slice(0,8)});for(let i=8;i<captions.length;i+=27)pages.push({lines:captions.slice(i,i+27)})}let urls=[];for(let i=0;i<pages.length;i++){let c=document.createElement('canvas');c.width=1080;c.height=1920;let ctx=c.getContext('2d');ctx.fillStyle='#f5f3eb';ctx.fillRect(0,0,1080,1920);ctx.fillStyle='#829274';ctx.font='24px Arial';ctx.fillText('ECHO27  /  JOURNAL',100,115);ctx.fillStyle='#8b9582';ctx.font='24px Arial';ctx.fillText(formatDate(selected),100,183);ctx.fillStyle='#354532';ctx.font='36px Georgia';let y=300;if(pages[i].photo){let img=new Image();await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src=pages[i].photo.src});let ratio=Math.min(880/img.width,1050/img.height),w=img.width*ratio,h=img.height*ratio;ctx.fillStyle='white';ctx.fillRect(90,260,900,h+25);ctx.drawImage(img,100+(880-w)/2,270,w,h);y=330+h;ctx.fillStyle='#354532'}for(let line of pages[i].lines){ctx.fillText(line,100,y);y+=49}ctx.strokeStyle='#d7dfcd';ctx.beginPath();ctx.moveTo(100,1740);ctx.lineTo(980,1740);ctx.stroke();ctx.fillStyle='#829274';ctx.font='22px Georgia';ctx.fillText('I’ll meet you in the future.',100,1805);ctx.font='20px Arial';if(includeName)ctx.fillText(settings.name.slice(0,45),100,1845);ctx.fillText(`${i+1} / ${pages.length}`,900,1805);let blob=await new Promise(res=>c.toBlob(res,'image/png'));urls.push({url:URL.createObjectURL(blob),name:`echo27-${selected}-${i+1}.png`})}results.innerHTML='<p>Your story cards are ready. Download each card:</p>'+urls.map((v,i)=>`<a class="secondary" style="display:inline-block;margin:4px" href="${v.url}" download="${v.name}">Card ${i+1} ↓</a>`).join('');if(urls.length===1)results.querySelector('a').click();$('modal').addEventListener('close',()=>setTimeout(()=>urls.forEach(v=>URL.revokeObjectURL(v.url)),10000),{once:true})}catch{results.textContent='Export failed. Try Print / Save as PDF instead.'}finally{$('imageExport').disabled=false}}
function exportPDF(){let e=current(),container=document.createElement('div');container.className='print-pages';let page=document.createElement('div');page.className='print-page';page.innerHTML=`<div class="print-brand">ECHO27 / JOURNAL</div><div class="print-date">${esc(formatDate(selected))}${$('exportName').checked?' · '+esc(settings.name):''}</div><h1>${esc(e.title||'A little of my day')}</h1><div>${esc(e.text)}</div>`+($('exportPhotos').checked?e.photos.map(p=>`<div style="break-inside:avoid;margin-top:25px"><img src="${p.src}" alt="${esc(p.caption)}"><p>${esc(p.caption)}</p></div>`).join(''):'')+'<p class="print-date">ECHO27 · I’ll meet you in the future.</p>';container.append(page);document.body.append(container);$('modal').close();Promise.all([...container.querySelectorAll('img')].map(img=>img.decode().catch(()=>{}))).then(()=>{window.print();container.remove()})}
let audio,musicBus,loop,playing=false,muted=false,step=0;const melodies={piano:[261.63,329.63,392,523.25,440,392,329.63,293.66],bells:[523.25,659.25,783.99,659.25,587.33,523.25,440,392],warm:[130.81,164.81,196,164.81,146.83,174.61,220,196]};
function note(){if(!audio||audio.state!=='running')return;let now=audio.currentTime,f=melodies[$('track').value][step++%8];[f,f/2,f*1.5].forEach((freq,i)=>{let o=audio.createOscillator(),g=audio.createGain();o.type=$('track').value==='warm'?'sine':'sine';o.frequency.value=freq;g.gain.setValueAtTime(0,now);g.gain.linearRampToValueAtTime(.045/(i+1),now+.08);g.gain.exponentialRampToValueAtTime(.0001,now+3.5);o.connect(g);g.connect(musicBus);o.start(now);o.stop(now+4)})}
