function stopMusic(){clearInterval(loop);playing=false;if(audio&&musicBus)musicBus.gain.setTargetAtTime(0,audio.currentTime,.15);$('playMusic').textContent='▶';$('playMusic').setAttribute('aria-label','Play background music')}
$('playMusic').onclick=()=>{if(playing)stopMusic();else{muted=false;startMusic()}};$('muteMusic').onclick=()=>{muted=!muted;if(muted)stopMusic();else startMusic();$('muteMusic').textContent=muted?'♬̸':'♫';$('muteMusic').setAttribute('aria-label',muted?'Unmute music':'Mute music')};$('volume').oninput=()=>{if(musicBus)musicBus.gain.setTargetAtTime(playing?+$('volume').value/100:0,audio.currentTime,.15)};$('track').onchange=()=>{step=0;$('trackLabel').textContent=$('track').selectedOptions[0].text+' · Sample instrumental';if(!muted)startMusic()};document.addEventListener('pointerdown',()=>startMusic(),{once:true});
